import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

batched_mm_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void batched_mm_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    const int batch_size,
    const int M,
    const int K,
    const int N
){
    int batch = blockIdx.z;
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < M && col < N) {
        float val = 0.0f;
        for (int i = 0; i < K; i++) {
            val += A[batch * M * K + row * K + i] * B[batch * K * N + i * N + col];
        }
        C[batch * M * N + row * N + col] = val;
    }
}

torch::Tensor batched_mm_cuda(torch::Tensor A, torch::Tensor B) {
    // A shape: (batch_size, M, K)
    // B shape: (batch_size, K, N)
    const auto batch_size = A.size(0);
    const auto M = A.size(1);
    const auto K = A.size(2);
    const auto N = B.size(2);

    auto C = torch::zeros({batch_size, M, N}, A.options());

    dim3 block(16, 16);
    dim3 grid((M + block.x - 1) / block.x,
              (N + block.y - 1) / block.y,
              batch_size);

    batched_mm_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        batch_size, M, K, N
    );
    return C;
}
"""

batched_mm_cpp_source = r"torch::Tensor batched_mm_cuda(torch::Tensor A, torch::Tensor B);"

batched_mm = load_inline(
    name="batched_mm",
    cpp_sources=batched_mm_cpp_source,
    cuda_sources=batched_mm_source,
    functions=["batched_mm_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.batched_mm = batched_mm

    def forward(self, A, B):
        return self.batched_mm.batched_mm_cuda(A, B)
